<?php
namespace App\Http\Controllers;use App\Models\Branch;use App\Models\City;use App\Models\CourseType;use App\Models\Faq;use App\Models\TheoryCourse;use App\Models\TheoryCoursePage;use Illuminate\Http\Request;use Illuminate\View\View;
class TheoryCoursePageController extends Controller {public function index(Request $r):View{$courses=TheoryCourse::where('is_active',true)->with(['type','city','branch'])->when($r->course_type_id,fn($q,$id)=>$q->where('course_type_id',$id))->when($r->city_id,fn($q,$id)=>$q->where('city_id',$id))->when($r->branch_id,fn($q,$id)=>$q->where('branch_id',$id))->orderBy('sort_order')->paginate(9)->withQueryString();return view('pages.theory-courses',['courses'=>$courses,'types'=>CourseType::where('is_active',true)->orderBy('name')->get(),'cities'=>City::where('is_active',true)->orderBy('name')->get(),'branches'=>Branch::where('is_active',true)->orderBy('name')->get(),'faqs'=>Faq::where('is_active',true)->orderBy('sort_order')->get(),'settings'=>TheoryCoursePage::first()]);}public function show(TheoryCourse $theoryCourse):View{abort_unless($theoryCourse->is_active,404);return view('pages.theory-course-details',['course'=>$theoryCourse->load(['type','city','branch'])]);}}
